import{c as t,Q as a,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"A Survey of Context Engineering for Large Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2507.13334","title":"A Survey of Context Engineering for Large Language Models","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2507.13334,"authors":["Lingrui Mei","Jiayu Yao","Yuyao Ge","Yiwei Wang","Baolong Bi","Yujun Cai","Jiazhi Liu","Mingyu Li","Zhong-Zhi Li","Duzhen Zhang","Chenlin Zhou","Jiayi Mao","Tianze Xia","Jiafeng Guo","Shenghua Liu"],"domains":["cs.CL","context engineering","survey"],"html":"https://arxiv.org/html/2507.13334v1","pdf_path":"pdfs/2507.13334.pdf","published_date":"2025-07-17T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-07-17-survey-context-engineering-llms-2507-13334.md","filePath":"research/papers/2025-07-17-survey-context-engineering-llms-2507-13334.md","lastUpdated":1785909234000}'),o={name:"research/papers/2025-07-17-survey-context-engineering-llms-2507-13334.md"};function i(s,e,l,g,c,d){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="a-survey-of-context-engineering-for-large-language-models" tabindex="-1">A Survey of Context Engineering for Large Language Models <a class="header-anchor" href="#a-survey-of-context-engineering-for-large-language-models" aria-label="Permalink to &quot;A Survey of Context Engineering for Large Language Models&quot;">​</a></h1><p><strong>Authors</strong>: Lingrui Mei, Jiayu Yao, Yuyao Ge, Yiwei Wang, Baolong Bi, Yujun Cai, Jiazhi Liu, Mingyu Li, Zhong-Zhi Li, Duzhen Zhang, Chenlin Zhou, Jiayi Mao, Tianze Xia, Jiafeng Guo, Shenghua Liu <strong>Published</strong>: July 17, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2507.13334" target="_blank" rel="noreferrer">https://arxiv.org/abs/2507.13334</a> · <a href="https://arxiv.org/html/2507.13334v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2507.13334 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2507.13334" target="_blank" rel="noreferrer">research/papers/pdfs/2507.13334.pdf</a> (166 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>The performance of Large Language Models (LLMs) is fundamentally determined by the contextual information provided during inference. This survey introduces Context Engineering, a formal discipline that transcends simple prompt design to encompass the systematic optimization of information payloads for LLMs. We present a comprehensive taxonomy decomposing Context Engineering into its foundational components and the sophisticated implementations that integrate them into intelligent systems. We first examine the foundational components: context retrieval and generation, context processing and context management. We then explore how these components are architecturally integrated to create sophisticated system implementations: retrieval-augmented generation (RAG), memory systems and tool-integrated reasoning, and multi-agent systems. Through this systematic analysis of over 1400 research papers, our survey not only establishes a technical roadmap for the field but also reveals a critical research gap: a fundamental asymmetry exists between model capabilities. While current models, augmented by advanced context engineering, demonstrate remarkable proficiency in understanding complex contexts, they exhibit pronounced limitations in generating equally sophisticated, long-form outputs. Addressing this gap is a defining priority for future research. Ultimately, this survey provides a unified framework for both researchers and engineers advancing context-aware AI.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>Context Engineering</strong> 作為正式學科，超越 prompt design，系統化定義 LLM 推論時 information payload 的最佳化框架</li><li>建立兩層 taxonomy：foundational components（context retrieval &amp; generation、context processing、context management）與 system implementations（RAG、memory systems、tool-integrated reasoning、multi-agent systems）</li><li>系統分析逾 <strong>1,400 篇</strong>研究論文，涵蓋 context-aware AI 完整技術脈絡</li><li>識別關鍵研究缺口：模型在理解複雜 context 的能力遠優於生成等質量 long-form output 的能力（理解 vs 生成非對稱性）</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>無單一量化 benchmark 數字（survey 性質）；核心方法層發現：context retrieval、processing、management 三組件是所有 sophisticated system（RAG、memory、multi-agent）的共通底層</li><li>揭示「context comprehension vs context generation 非對稱性」為當前 LLM 最重要的能力落差，是未來研究首要議題</li><li>提供對研究者與工程師均適用的統一框架（unified framework for context-aware AI）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>Survey 涵蓋至 2025 年 7 月，快速演進領域存在時效性限制</li><li>1,400+ 論文覆蓋廣度高，但深度分析受篇幅制約；部分子領域可能處理較淺</li><li>「context generation gap」雖被識別為關鍵缺口，但論文本身未提供解法路徑，僅列為 future work 方向</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接對應 <code>.claude/rules/context-management.md</code></strong>：論文的 context management 分類（token budget、context processing）與 workspace 的 NLAH 原則、Compact 觸發機制、Prompt Caching 設計高度吻合；survey 提供學術支撐，可作為調整 context-management 規則的理論依據</li><li><strong>multi-agent systems 章節 ↔ <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>）</strong>：論文的 multi-agent 架構分析（fan-out、agent 協調、context 傳遞）直接對應 workspace 的委派決策準則與 hierarchical fan-out 上限 4 的設計；⚠️ 論文層次在學術描述，workspace 落地需額外考慮 <code>unverified_success</code> 閘門與 child 不 self-retry 等執行紀律 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>memory systems ↔ <code>memory/MEMORY.md</code> 長期記憶回路</strong>：論文的 memory system 分類（episodic/semantic/procedural）可指導 workspace MEMORY.md 結構演化；⚠️ 落地門檻：workspace 目前無向量檢索層，memory 仍是 flat markdown，論文方法需大幅簡化才可應用</li><li><strong>The Loop OBSERVE 階段 ↔ context retrieval</strong>：論文強調 context retrieval &amp; generation 是所有 intelligent system 基礎，對應 core.md OBSERVE「先讀後動」紀律——兩者共同前提是「正確的 context 先於行動」；survey 指出的 comprehension/generation 非對稱性亦解釋了為何 The Loop 需要明確 TEST 階段驗證輸出而非信任 LLM 自報</li></ul>',16)])])}const h=t(o,[["render",i]]);export{u as __pageData,h as default};
